#' Differential state or abundance across groups
#'
#' Test clusters (a cluster channel from explore) or populations between groups of samples
#' defined by a metadata field, with pairing and covariates as fixed effects. test "state"
#' (default) is diffcyt-DS-limma: per sample, the median of arcsinh(x / cofactor) of each
#' marker in each cluster or population (cofactor 5 for mass cytometry, 150 for fluorescence),
#' clusters with at least minCells cells in at least half the samples, a linear model per
#' cluster and marker weighted by the cells in each sample, limma's moderated t-statistics with
#' a mean-variance trend, and Benjamini-Hochberg adjustment across every cluster and marker
#' tested. By default it tests the markers the clustering did not use (state markers). test
#' "abundance" tests each cluster's share of the parent population with a quasi-binomial model.
#' Rows are sorted by p; logFC is the difference of the medians (contrast minus reference).
#'
#' @param group_by Metadata field that defines the groups. Required; a string.
#' @param clusters Cluster channel (default: the first one). Optional; a string.
#' @param cofactor arcsinh cofactor (default 5 for mass cytometry, 150 otherwise). Optional; a
#' number.
#' @param contrast The group tested against the reference (default: the second group).
#' Optional; a string.
#' @param covariates Other metadata fields in the model (e.g. batch). Optional; a list of
#' strings.
#' @param groups Groups to compare, the reference first (default: every value, sorted).
#' Optional; a list of strings.
#' @param limit Rows to return, lowest p first (default 40). Optional; a number.
#' @param markers Markers to test (default: those the clustering did not use). Optional; a list
#' of strings.
#' @param min_cells Cells a cluster needs in a sample (default 3). Optional; a number.
#' @param min_samples Samples that need minCells (default: half). Optional; a number.
#' @param pair_by Metadata field that pairs samples (e.g. subject), as a fixed effect.
#' Optional; a string.
#' @param parent Parent population of the clusters (default: all events). Optional; a string.
#' @param populations Populations to test instead of clusters (state only). Optional; a list of
#' strings.
#' @param test Marker medians (state, default) or cluster frequencies (abundance). Optional;
#' one of "state", "abundance".
#' @param cw A connection from cw_connect() (default: the last one made).
#' @return A cytoweave_result: the message and the data CytoWeave answered with.
#' @export
cw_differential_analysis <- function(group_by, clusters = NULL, cofactor = NULL, contrast = NULL, covariates = NULL, groups = NULL, limit = NULL, markers = NULL, min_cells = NULL, min_samples = NULL, pair_by = NULL, parent = NULL, populations = NULL, test = NULL, cw = cw_default()) {
  cw_call("differential_analysis", groupBy = group_by, clusters = clusters, cofactor = cofactor, contrast = contrast, covariates = .cw_array(covariates), groups = .cw_array(groups), limit = limit, markers = .cw_array(markers), minCells = min_cells, minSamples = min_samples, pairBy = pair_by, parent = parent, populations = .cw_array(populations), test = test, cw = cw)
}

